package.path = '/home/tim/.config/wezterm/?.lua;' .. package.path

local leader = { key = 'Space', mods = 'CTRL|SHIFT' }
local function set_leader(l)
    leader = l
end

local gui = {
    maximize = function()
        print('maximize ok')
    end,
    toast_notification = function(_, title, msg, _icon, ms)
        print(('TOAST[%dms] %s: %s'):format(ms, title, msg))
    end,
    effective_config = function()
        return { leader = leader }
    end,
}

local injected = {}
package.loaded['wezterm'] = {
    mux = {
        spawn_window = function()
            return {
                gui_window = function()
                    return gui
                end,
            },
                {
                    inject_output = function(_, data)
                        table.insert(injected, data)
                        print(('INJECT raw: %q'):format(data))
                        print('INJECT as terminal would show:')
                        print((data:gsub('\27', '<ESC>')))
                    end,
                }
        end,
    },
    on = function(name, fn)
        print('registered handler: ' .. name)
        _G.handler = fn
    end,
    timing = {
        call = function(secs, fn)
            print(('timing.call(%s) -> выполняем сразу'):format(secs))
            fn()
        end,
    },
    log_error = function(msg)
        print('LOG_ERROR: ' .. msg)
    end,
}

require('events.startup')

print('--- leader = CTRL|SHIFT + Space ---')
_G.handler({})

print('--- leader = nil (fallback) ---')
set_leader(nil)
_G.handler({})

print('--- leader = SUPER|CTRL + Space (mac) ---')
set_leader({ key = 'Space', mods = 'SUPER|CTRL' })
_G.handler({})

print('--- pane:inject_output падает ---')
local broken = require('events.startup')
print('ok, модуль переиспользуемый')

